render-mode.text:
${JSON.stringify((() => {
                const out = ec.service.sync().name('org.moqui.impl.ComponentServices.get#ConfView').call() || {}
                const error = ec.message.hasError() ? ec.message.errorsString : null
                ec.message.clearErrors()
                if (error || !out.view) return [{t: 'text', id: 'ConfViewError', style: 'error', text: error || 'The conf could not be read'}]
                const view = out.view
                const files = view.files || []
                const fileText = (at) => (files[at.file] ? files[at.file].label : '?') + ':' + at.line
                const rows = []
                const firstLine = (text) => String(text || '').split('\n')[0].slice(0, 120)
                const walk = (node, parent, key) => {
                    const attrs = (node.attrs || []).map(attr => attr.name + '=' + (attr.expanded != null ? attr.expanded : attr.value)
                        + (attr.class ? ' [' + attr.class + ']' : '') + (attr.pending ? ' (not running yet)' : '')).join(' ')
                    if (parent != null) {
                        if ((node.comments || []).length) rows.push({key: key + '#', parent, label: '# ' + firstLine(node.comments[0]), tc: ['', '']})
                        rows.push({key, parent, label: node.name + (node.key ? '[' + node.key + ']' : '') + (attrs ? ' ' + attrs : ''),
                            tc: [node.class, (node.sources || []).map(fileText).join(', ')]})
                    }
                    ;(node.children || []).forEach((child, at) => walk(child, parent == null ? '' : key, key + '.' + at))
                }
                walk(view.root, null, 'c')
                return [{t: 'text', id: 'ConfViewFiles', text: 'Merged from ' + files.map(file => file.label).join(', ')
                        + ' · ' + view.wouldApply + ' change(s) a reload would apply, ' + view.pendingRestart + ' waiting for a restart'},
                    {t: 'component', name: 'tree', props: {rows, columns: ['Setting', 'Class', 'From']}}]
            })())}
